create function public.append_ledger(p_account uuid,p_delta numeric,p_kind text,p_reason text,p_event uuid default null,p_request uuid default null,p_reverse uuid default null) returns uuid language plpgsql security definer set search_path='' as $$declare i uuid;b numeric;whole boolean;begin perform 1 from public.obligation_accounts where id=p_account for update;if not found then raise exception 'ACCOUNT_NOT_FOUND';end if;select t.integer_only into whole from public.obligation_types t join public.obligation_accounts a on a.type_id=t.id where a.id=p_account;if p_delta=0 or p_delta<>round(p_delta,3) or (whole and p_delta<>trunc(p_delta)) then raise exception 'INVALID_QUANTITY';end if;select coalesce(sum(delta),0) into b from public.obligation_ledger where account_id=p_account;if b+p_delta<0 then raise exception 'NEGATIVE_BALANCE';end if;insert into public.obligation_ledger(account_id,delta,kind,reason,source_event_id,source_request_id,reverse_of,created_by) values(p_account,p_delta,p_kind,p_reason,p_event,p_request,p_reverse,auth.uid()) returning id into i;update public.obligation_accounts set version=version+1 where id=p_account;return i;end$$;
create function public.ensure_account(p_soop text,p_nickname text,p_type uuid) returns uuid language plpgsql security definer set search_path='' as $$declare v uuid;a uuid;begin insert into public.viewer_accounts(soop_id,nickname) values(trim(p_soop),trim(p_nickname)) on conflict(soop_id) do update set nickname=excluded.nickname returning id into v;insert into public.obligation_accounts(viewer_id,type_id) values(v,p_type) on conflict(viewer_id,type_id) do update set viewer_id=excluded.viewer_id returning id into a;return a;end$$;
create function public.write_entry(p_data jsonb,p_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;a uuid;i uuid;v integer;d numeric:=(p_data->>'quantity')::numeric;k text:=p_data->>'kind';begin perform public.assert_admin();r=public.operation_begin('entry',p_key,p_data);if r is not null then return r;end if;if length(trim(p_data->>'reason'))<1 then raise exception 'REASON_REQUIRED';end if;if k not in ('acquire','adjust','fulfill','invalidate','set') then raise exception 'INVALID_KIND';end if;if k in ('acquire','fulfill','invalidate') and d<=0 then raise exception 'INVALID_QUANTITY';end if;perform 1 from public.obligation_types where id=(p_data->>'typeId')::uuid and active;if not found then raise exception 'TYPE_NOT_FOUND';end if;a=public.ensure_account(p_data->>'soop',p_data->>'nickname',(p_data->>'typeId')::uuid);select version into v from public.obligation_accounts where id=a for update;if p_data ? 'expectedVersion' and v is distinct from (p_data->>'expectedVersion')::integer then raise exception 'VERSION_CONFLICT' using errcode='40001';end if;
 if k='set' then if not p_data ? 'expectedVersion' then raise exception 'VERSION_REQUIRED';end if;select d-coalesce(sum(delta),0) into d from public.obligation_ledger where account_id=a;k='adjust';end if;if k in ('fulfill','invalidate') then d=-d;end if;
 if d<>0 then i=public.append_ledger(a,d,k,p_data->>'reason');end if;perform public.audit('ledger.'||k,a::text,jsonb_build_object('delta',d));return public.operation_finish('entry',p_key,jsonb_build_object('id',i,'accountId',a));end$$;
create function public.reverse_entry(p_id uuid,p_reason text,p_version integer,p_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;e public.obligation_ledger;i uuid;begin perform public.assert_admin();r=public.operation_begin('reverse',p_key,jsonb_build_object('id',p_id,'reason',p_reason,'version',p_version));if r is not null then return r;end if;select * into e from public.obligation_ledger where id=p_id;if not found or e.kind in ('request_complete','request_reopen','reverse') then raise exception 'REVERSE_NOT_ALLOWED';end if;if length(trim(p_reason))=0 then raise exception 'REASON_REQUIRED';end if;perform 1 from public.obligation_accounts where id=e.account_id and version=p_version for update;if not found then raise exception 'VERSION_CONFLICT' using errcode='40001';end if;if exists(select 1 from public.obligation_ledger where reverse_of=p_id) then raise exception 'ALREADY_REVERSED' using errcode='23505';end if;i=public.append_ledger(e.account_id,-e.delta,'reverse',p_reason,null,null,p_id);perform public.audit('ledger.reverse',p_id::text);return public.operation_finish('reverse',p_key,jsonb_build_object('id',i));end$$;
create function public.submit_request(p_data jsonb,p_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;i uuid;c text;t timestamptz;begin r=public.operation_begin('request.submit',p_key,p_data);if r is not null then return r;end if;insert into public.photo_requests(nickname,soop_id,message) values(p_data->>'nickname',p_data->>'soop',p_data->>'message') returning id,receipt,created_at into i,c,t;return public.operation_finish('request.submit',p_key,jsonb_build_object('receipt',c,'createdAt',t));end$$;
create function public.edit_request(p_id uuid,p_data jsonb,p_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;r public.photo_requests;s text:=p_data->>'status';a uuid:=(p_data->>'accountId')::uuid;q numeric:=(p_data->>'quantity')::numeric;i uuid;e public.obligation_ledger;begin perform public.assert_admin();result=public.operation_begin('request.edit',p_key,jsonb_build_object('id',p_id,'data',p_data));if result is not null then return result;end if;select * into r from public.photo_requests where id=p_id for update;if not found or r.version is distinct from (p_data->>'expectedVersion')::integer then raise exception 'VERSION_CONFLICT' using errcode='40001';end if;
 if s<>r.status then if not coalesce((p_data->>'confirmed')::boolean,false) then raise exception 'CONFIRM_REQUIRED';end if;
 if not(case r.status when 'received' then s in ('reviewing','on_hold','cancelled') when 'reviewing' then s in ('in_progress','on_hold','cancelled') when 'in_progress' then s in ('completed','on_hold','cancelled') when 'on_hold' then s in ('reviewing','cancelled') when 'completed' then s='reviewing' when 'cancelled' then s='reviewing' else false end) then raise exception 'INVALID_TRANSITION';end if;
 if r.status in ('completed','cancelled') and length(trim(p_data->>'reason'))=0 then raise exception 'REASON_REQUIRED';end if;end if;
 if r.status='completed' then a=r.account_id;q=r.quantity;end if;
 if a is not null and r.status<>'completed' and not coalesce((p_data->>'verified')::boolean,false) then raise exception 'ACCOUNT_VERIFICATION_REQUIRED';end if;
 if a is not null then perform 1 from public.obligation_accounts oa join public.obligation_types ot on ot.id=oa.type_id where oa.id=a and (not ot.integer_only or q=trunc(q)) for update of oa;if not found then raise exception 'INVALID_QUANTITY';end if;end if;
 i=r.completion_entry;
 if s='completed' and r.status<>s and a is not null then i=public.append_ledger(a,-q,'request_complete','방셀 신청 완료',null,p_id);end if;
 if r.status='completed' and s<>r.status and r.completion_entry is not null then select * into e from public.obligation_ledger where id=r.completion_entry;perform public.append_ledger(e.account_id,-e.delta,'request_reopen',p_data->>'reason',null,p_id,e.id);i=null;end if;
 update public.photo_requests set status=s,memo=p_data->>'memo',account_id=a,quantity=q,completion_entry=i,version=version+1 where id=p_id;perform public.audit('request.'||s,p_id::text,jsonb_build_object('from',r.status,'accountId',a));return public.operation_finish('request.edit',p_key,jsonb_build_object('id',p_id,'version',r.version+1));end$$;
create function public.read_accounts(p_q text default '',p_type uuid default null,p_remaining boolean default false,p_page integer default 1,p_size integer default 20) returns jsonb language sql stable security definer set search_path='' as $$with rows as(select a.id,v.soop_id as soop,v.nickname,a.type_id as "typeId",t.name as item,t.unit,t.integer_only as integer,a.version,coalesce(sum(l.delta) filter(where l.kind in ('acquire','roulette')),0) as acquired,coalesce(sum(l.delta) filter(where l.kind in ('adjust','invalidate','reverse','request_reopen')),0) as adjusted,-coalesce(sum(l.delta) filter(where l.kind in ('fulfill','request_complete')),0) as fulfilled,coalesce(sum(l.delta),0) as balance from public.obligation_accounts a join public.viewer_accounts v on v.id=a.viewer_id join public.obligation_types t on t.id=a.type_id left join public.obligation_ledger l on l.account_id=a.id where (p_type is null or t.id=p_type) and (p_q='' or position(lower(p_q) in lower(v.nickname||' '||v.soop_id))>0) group by a.id,v.soop_id,v.nickname,t.name,t.unit,t.integer_only),filtered as(select * from rows where not p_remaining or balance>0),paged as(select * from filtered order by nickname collate "C",soop collate "C",id limit least(greatest(p_size,1),100) offset (greatest(p_page,1)-1)*least(greatest(p_size,1),100))select jsonb_build_object('rows',coalesce((select jsonb_agg(to_jsonb(paged)) from paged),'[]'),'total',(select count(*) from filtered))$$;
create function public.read_public_history(p_account uuid,p_page integer default 1) returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(to_jsonb(x)),'[]') from (select l.id,l.account_id as "accountId",l.delta,l.kind,l.created_at as time,exists(select 1 from public.obligation_ledger r where r.reverse_of=l.id) as reversed from public.obligation_ledger l where l.account_id=p_account order by l.created_at desc,l.id limit 50 offset (greatest(p_page,1)-1)*50)x$$;
create function public.save_obligation_type(p_id uuid,p_data jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare i uuid:=coalesce(p_id,gen_random_uuid());begin perform public.assert_admin();if p_id is not null and exists(select 1 from public.obligation_accounts where type_id=p_id) and exists(select 1 from public.obligation_types where id=p_id and (unit<>p_data->>'unit' or integer_only<>(p_data->>'integer')::boolean)) then raise exception 'TYPE_UNIT_IN_USE';end if;insert into public.obligation_types(id,name,unit,integer_only,active) values(i,p_data->>'name',p_data->>'unit',(p_data->>'integer')::boolean,(p_data->>'active')::boolean) on conflict(id) do update set name=excluded.name,unit=excluded.unit,integer_only=excluded.integer_only,active=excluded.active;perform public.audit('obligation_type.save',i::text);return jsonb_build_object('id',i);end$$;
revoke all on function public.append_ledger(uuid,numeric,text,text,uuid,uuid,uuid),public.ensure_account(text,text,uuid),public.write_entry(jsonb,uuid),public.reverse_entry(uuid,text,integer,uuid),public.submit_request(jsonb,uuid),public.edit_request(uuid,jsonb,uuid),public.read_accounts(text,uuid,boolean,integer,integer),public.read_public_history(uuid,integer),public.save_obligation_type(uuid,jsonb) from public;
grant execute on function public.write_entry(jsonb,uuid),public.reverse_entry(uuid,text,integer,uuid),public.edit_request(uuid,jsonb,uuid),public.save_obligation_type(uuid,jsonb) to authenticated;
grant execute on function public.read_accounts(text,uuid,boolean,integer,integer),public.read_public_history(uuid,integer) to anon,authenticated;
grant execute on function public.submit_request(jsonb,uuid) to service_role;
